def babylonian_squareroot(number):
    if number < 0:
        raise ValueError("Cannot compute square root of negative number")
    if number == 0:
        return 0

    # Initial guess
    x = number / 2

    # Iterate until convergence
    while True:
        # Babylonian method formula: x_new = (x + number/x) / 2
        x_new = (x + number / x) / 2

        # Check for convergence (relative error threshold)
        if abs(x_new - x) < 1e-10:
            break

        x = x_new

    return x_new

