def count_binary_seq(n):
    # For a binary sequence of length 2n, we need the sum of first n bits
    # to equal the sum of last n bits.
    # Let's say both sums equal k, where k can range from 0 to n.
    # For a given k, the number of ways to choose k ones in first n bits is C(n,k)
    # and the number of ways to choose k ones in last n bits is also C(n,k)
    # So for each k, the contribution is C(n,k) * C(n,k) = C(n,k)^2

    import math

    def combination(n, r):
        if r > n or r < 0:
            return 0
        return math.factorial(n) // (math.factorial(r) * math.factorial(n - r))

    total = 0
    for k in range(n + 1):
        total += combination(n, k) ** 2

    return total

