def get_max_sum(n):
    # Memoization dictionary to store computed values
    memo = {}

    def f(num):
        if num == 0:
            return 0

        # Check if already computed
        if num in memo:
            return memo[num]

        # Compute using the given equation
        # f(n) = max( f(n/2) + f(n/3) + f(n/4) + f(n/5), n )
        result = max(f(num // 2) + f(num // 3) + f(num // 4) + f(num // 5), num)

        # Store in memo and return
        memo[num] = result
        return result

    return f(n)

