def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    # Find all prime factors of a
    prime_factors = []
    temp = a

    for i in range(2, int(a**0.5) + 1):
        while temp % i == 0:
            if is_prime(i):
                prime_factors.append(i)
            temp //= i

    # If temp > 1, then it's also a prime factor
    if temp > 1:
        prime_factors.append(temp)

    # Check if we have exactly 3 prime factors and their product equals a
    if len(prime_factors) == 3:
        product = 1
        for factor in prime_factors:
            product *= factor
        return product == a

    return False
