def set_left_most_unset_bit(n):
    if n == 0:
        return 1

    # Find the leftmost unset bit
    temp = n
    pos = 0

    # Handle negative numbers by using unsigned representation
    while temp != 0:
        if (temp & 1) == 0:
            break
        temp >>= 1
        pos += 1

    # If all bits are set, we need to add a new bit at the leftmost position
    if temp == 0:
        return n | (n + 1)

    # Set the leftmost unset bit
    return n | (1 << pos)

