def cal_sum(n):
    if n <= 0:
        return 0

    # Perrin sequence: P(0)=3, P(1)=0, P(2)=2, P(n)=P(n-2)+P(n-3)
    if n == 1:
        return 3
    elif n == 2:
        return 3
    elif n == 3:
        return 5

    # Initialize first three Perrin numbers
    p0, p1, p2 = 3, 0, 2
    total = 5  # Sum of P(0) + P(1) + P(2) = 3 + 0 + 2 = 5

    # Calculate remaining Perrin numbers and add to sum
    for i in range(3, n):
        next_p = p0 + p1
        total += next_p
        # Shift the window
        p0, p1, p2 = p1, p2, next_p

    return total

