def is_undulating(n):
    # Convert number to string to easily access digits
    s = str(n)

    # Undulating numbers must have at least 3 digits
    if len(s) < 3:
        return False

    # First digit must be different from second digit
    if s[0] == s[1]:
        return False

    # Check that digits alternate properly
    for i in range(2, len(s)):
        # If current digit is same as previous digit, it's not undulating
        if s[i] == s[i-1]:
            return False
        # If current digit is same as the digit before previous, it's not undulating
        if i >= 2 and s[i] == s[i-2]:
            return False

    # Check that pattern alternates correctly: ababab...
    # Every even index should match first digit, every odd index should match second digit
    for i in range(len(s)):
        if i % 2 == 0:
            if s[i] != s[0]:
                return False
        else:
            if s[i] != s[1]:
                return False

    return True

