def set_left_most_unset_bit(n):
    if n == 0:
        return 1

    # Find the leftmost unset bit
    temp = n
    pos = 0

    # Keep shifting right until we find an unset bit (0)
    while temp > 0:
        if (temp & 1) == 0:
            break
        temp >>= 1
        pos += 1

    # If all bits are set, we need to set the next bit
    if temp == 0 and (n & (n + 1)) != 0:
        # All bits are set, so we need to set the bit beyond the highest set bit
        return n | (n + 1)

    # Set the leftmost unset bit
    return n | (1 << pos)

