def parse_date(date_string):
    return datetime.strptime(date_string, '%Y-%m-%d')

def main():
    # Dictionary to store transactions for each account
    account_transactions = {}

    # Read the CSV file
    try:
        with open('transactions.csv', 'r') as file:
            reader = csv.DictReader(file)
            for row in reader:
                account_id = row['account_id']
                date = parse_date(row['date'])
                amount = float(row['amount'])

                if account_id not in account_transactions:
                    account_transactions[account_id] = []

                account_transactions[account_id].append((date, amount))
    except FileNotFoundError:
        print("Error: transactions.csv file not found")
        return
    except Exception as e:
        print(f"Error reading file: {e}")
        return

    # Find accounts with 3+ transactions over 10000 in any 7-day window
    qualifying_accounts = {}

    for account_id, transactions in account_transactions.items():
        # Sort transactions by date
        transactions.sort(key=lambda x: x[0])

        # Check all possible 7-day windows
        for i in range(len(transactions)):
            start_date = transactions[i][0]
            end_date = start_date + timedelta(days=7)

            # Count transactions in this window
            count = 0
            for date, amount in transactions:
                if start_date <= date < end_date and amount > 10000:
                    count += 1

            # If we have 3 or more qualifying transactions
            if count >= 3:
                if account_id not in qualifying_accounts or start_date < qualifying_accounts[account_id][1]:
                    qualifying_accounts[account_id] = (count, start_date)

    # Print results
    for account_id, (count, start_date) in sorted(qualifying_accounts.items()):
        print(f"{account_id} {start_date.strftime('%Y-%m-%d')}")

if __name__ == "__main__":
