    p0, p1, p2 = 3, 0, 2
    total = 5  # Sum of first 3 terms (3+0+2)

    for i in range(3, n):
        p_next = p0 + p1
        total += p_next
        p0, p1, p2 = p1, p2, p_next

    return total

