        """Convert a value to float for comparison"""
        if isinstance(value, (int, float)):
            return float(value)
        elif isinstance(value, str):
            # Replace comma with dot for decimal representation
            normalized_str = value.replace(',', '.')
            return float(normalized_str)
        else:
            raise TypeError("Unsupported type for comparison")

    # Convert both values to float for comparison
    a_float = convert_to_float(a)
    b_float = convert_to_float(b)

    # Compare the float values
    if a_float > b_float:
        return a
    elif b_float > a_float:
        return b
    else:
        return None
