def count_binary_seq(n):
    # For a binary sequence of length 2n, we need the sum of first n bits
    # to equal the sum of last n bits.
    # Let's say the sum is k (where 0 <= k <= n).
    # Number of ways to choose k ones from first n bits: C(n,k)
    # Number of ways to choose k ones from last n bits: C(n,k)
    # Total ways for this particular sum k: C(n,k) * C(n,k) = C(n,k)^2

    import math

    def combination(n, r):
        if r > n or r < 0:
            return 0
        return math.factorial(n) // (math.factorial(r) * math.factorial(n - r))

    total_count = 0
    for k in range(n + 1):
        total_count += combination(n, k) ** 2

    return total_count

