def is_undulating(n):
    # Convert number to string to work with individual digits
    s = str(n)

    # Undulating numbers must have at least 3 digits
    if len(s) < 3:
        return False

    # First digit must be different from second digit
    if s[0] == s[1]:
        return False

    # Check that pattern alternates: digit[i] != digit[i+1] and digit[i] == digit[i+2]
    for i in range(len(s) - 2):
        if s[i] != s[i + 1] or s[i] != s[i + 2]:
            return False

    # Verify the alternating pattern continues throughout
    for i in range(0, len(s) - 2, 2):
        if i + 2 < len(s) and s[i] != s[i + 2]:
            return False
        if i + 3 < len(s) and s[i + 1] != s[i + 3]:
            return False

    # Actually, let's simplify - check that it's of form aba where a != b
    # and the pattern alternates correctly
    first = s[0]
    second = s[1]

    # Check alternating pattern: a, b, a, b, a, b...
    for i in range(len(s)):
        if i % 2 == 0:
            if s[i] != first:
                return False
        else:
            if s[i] != second:
                return False

    # Make sure first and second are different
    return first != second

