def count_vowel_runs(word):
    """Return how many separate runs of consecutive vowels (a, e, i, o, u; case-insensitive)
    the word contains.

    count_vowel_runs("banana") == 3
    count_vowel_runs("rhythm") == 0
    """
    if not word:
        return 0

    vowels = set('aeiouAEIOU')
    run_count = 0
    in_vowel_run = False

    for char in word:
        if char in vowels:
            if not in_vowel_run:
                run_count += 1
                in_vowel_run = True
        else:
            in_vowel_run = False

    return run_count

